package com.ftk.tpip.control.api.release;
import com.ftk.tpip.control.application.release.WorkspaceAssetQueryService;import com.ftk.tpip.release.domain.model.*;import jakarta.validation.constraints.*;import java.util.Set;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@Validated @RestController @RequestMapping("/control/v1/verification-drift-workbench/workspace-asset-views")
public class WorkspaceAssetQueryController{private final WorkspaceAssetQueryService queries;public WorkspaceAssetQueryController(WorkspaceAssetQueryService q){queries=q;}
 @GetMapping public WorkspaceAssetQueryService.WorkspacePage workspaces(@RequestParam(required=false)Set<WorkspaceLifecycleStatus> lifecycleStatus,@RequestParam(required=false)Set<WorkspaceRiskLevel> riskLevel,@RequestParam(required=false)@Size(min=1,max=32)String environmentCode,@RequestParam(required=false)@Size(min=1,max=180)String keyword,@RequestParam(defaultValue="0")@Min(0)int page,@RequestParam(defaultValue="20")@Min(1)@Max(100)int size){return queries.workspaces(new WorkspaceAssetQueryService.Filter(lifecycleStatus,riskLevel,environmentCode,keyword),page,size);}
 @GetMapping("/{workspaceId}") public WorkspaceAssetQueryService.WorkspaceDetail workspace(@PathVariable@Positive long workspaceId,@RequestParam(defaultValue="20")@Min(1)@Max(100)int limit){return queries.workspace(workspaceId,limit);}}
